const slugMap = new Map<string, ManifestEntry>(
  MANIFEST_ENTRIES.map((entry) => [entry.slug, entry])
);

export function getManifestEntryBySlug(slug: string): ManifestEntry | undefined {
  return slugMap.get(slug);
}

export function getAllManifestSlugs(): string[] {
  return MANIFEST_ENTRIES.map((e) => e.slug);
}

export function getManifestEntriesByPattern(pattern: PatternId): ManifestEntry[] {
  return MANIFEST_ENTRIES.filter((e) => e.pattern === pattern);
}

export function getManifestEntriesByWave(wave: string): ManifestEntry[] {
  return MANIFEST_ENTRIES.filter((e) => e.wave === wave);
}
